import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './App.css';

function Registro() {
  const [formData, setFormData] = useState({
    nombre: '',
    correo: '',
    contraseña: '',
    direccion: '',
    ciudad: '',
    telefono: ''
  });

  const [mensaje, setMensaje] = useState('');

  const handleChange = (e) => {
    setFormData({...formData, [e.target.name]: e.target.value});
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validación rápida de campos
    for (const key in formData) {
      if (!formData[key]) {
        setMensaje('Todos los campos son obligatorios.');
        return;
      }
    }

    try {
      // Simulación de envío al backend
      console.log('Datos de registro:', formData);
      setMensaje('Registro exitoso!');
      setFormData({
        nombre: '',
        correo: '',
        contraseña: '',
        direccion: '',
        ciudad: '',
        telefono: ''
      });
    } catch (error) {
      setMensaje('Error al registrar. Intenta nuevamente.');
      console.error(error);
    }
  };

  return (
    <div>
      <header>
        <div className="logo-contenedor">
          <img src="/Logotipo.jpg" alt="Logo Taller Robledo" className="logo" />
          <div className="texto-logo">
            <span className="slogan">FABRICACIÓN DE VOLCOS</span>
            <span className="nombre">TALLER ROBLEDO</span>
          </div>
        </div>
        <nav>
          <ul className="menu">
            <li><Link to="/">Inicio</Link></li>
            <li><Link to="/volcos">Volcos</Link></li>
            <li><Link to="/cotizacion">Cotización</Link></li>
            <li><Link to="/contacto">Contacto</Link></li>
            <li><Link to="/opiniones">Opiniones</Link></li>
            <li><Link to="/registro" className="active">Registro</Link></li>
          </ul>
        </nav>
      </header>

      <main className="auth-section">
        <div className="auth-container">
          <h2>Registro de Usuario</h2>
          <form className="form-registro" onSubmit={handleSubmit}>
            <label htmlFor="nombre">Nombre completo:</label>
            <input
              type="text"
              id="nombre"
              name="nombre"
              placeholder="Ingresa tu nombre"
              value={formData.nombre}
              onChange={handleChange}
              required
            />

            <label htmlFor="correo">Correo electrónico:</label>
            <input
              type="email"
              id="correo"
              name="correo"
              placeholder="ejemplo@correo.com"
              value={formData.correo}
              onChange={handleChange}
              required
            />

            <label htmlFor="contraseña">Contraseña:</label>
            <input
              type="password"
              id="contraseña"
              name="contraseña"
              placeholder="•••••••"
              value={formData.contraseña}
              onChange={handleChange}
              required
            />

            <label htmlFor="direccion">Dirección:</label>
            <input
              type="text"
              id="direccion"
              name="direccion"
              placeholder="Ej: Calle 10 #15-23"
              value={formData.direccion}
              onChange={handleChange}
              required
            />

            <label htmlFor="ciudad">Ciudad:</label>
            <input
              type="text"
              id="ciudad"
              name="ciudad"
              placeholder="Tu ciudad"
              value={formData.ciudad}
              onChange={handleChange}
              required
            />

            <label htmlFor="telefono">Teléfono:</label>
            <input
              type="tel"
              id="telefono"
              name="telefono"
              placeholder="Ej: 3001234567"
              value={formData.telefono}
              onChange={handleChange}
              required
            />

            <button type="submit" className="btn-primary">Registrar cuenta</button>
            {mensaje && <p className="mensaje-form">{mensaje}</p>}
          </form>

          <p className="auth-link">
            ¿Ya tienes una cuenta? <Link to="/">Inicia sesión aquí</Link>
          </p>
        </div>
      </main>

      <footer className="footer">
        <div className="footer-left">
          <p>Taller Robledo | 📞 314 880 5733</p>
        </div>
        <div className="footer-right">
          <p>© 2025 Todos los derechos reservados</p>
        </div>
      </footer>
    </div>
  );
}

export default Registro;
